using System.Net.Http.Headers;using System.Net.Sockets;using System.Runtime.CompilerServices;using System.Text;using System.Text.Json;using IcpaaS.Core.Configuration;using IcpaaS.Core.Telephony;using Microsoft.Extensions.Options;
namespace IcpaaS.Telephony;
public abstract class ConfigurableEngine(string key,TelephonyEngineKind kind,EngineOptions options):ITelephonyEngine{protected EngineOptions Options{get;}=options;public string EngineKey{get;}=key;public TelephonyEngineKind Kind{get;}=kind;public abstract Task<EngineHealth> ProbeAsync(CancellationToken ct);public virtual Task<RegistrationResult> RegisterEndpointAsync(EndpointSpec e,CancellationToken ct)=>No<RegistrationResult>("Endpoint provisioning is managed by provisioning jobs");public abstract Task<OriginateResult> OriginateAsync(CallRequest r,CancellationToken ct);public virtual Task AnswerAsync(CallRef c,CancellationToken ct)=>No("Answer");public virtual Task BridgeAsync(CallRef a,CallRef b,CancellationToken ct)=>No("Bridge");public virtual Task TransferAsync(CallRef c,TransferRequest r,CancellationToken ct)=>No("Transfer");public virtual Task HoldAsync(CallRef c,bool e,CancellationToken ct)=>No("Hold");public virtual Task SendDtmfAsync(CallRef c,string d,CancellationToken ct)=>No("DTMF");public virtual Task HangupAsync(CallRef c,string r,CancellationToken ct)=>No("Hangup");public virtual async IAsyncEnumerable<TelephonyEvent> SubscribeAsync([EnumeratorCancellation]CancellationToken ct){await Task.CompletedTask;yield break;}protected Task No(string op)=>Task.FromException(new NotSupportedException($"{op} unavailable for {EngineKey}"));protected Task<T>No<T>(string m)=>Task.FromException<T>(new NotSupportedException(m));protected static void Valid(CallRequest r){if(!System.Text.RegularExpressions.Regex.IsMatch(r.Destination,"^\\+[1-9][0-9]{6,14}$|^[A-Za-z0-9_.-]{2,64}$"))throw new ArgumentException("Invalid destination");}}
public sealed class FreeSwitchEngine:IcpaaS.Telephony.ConfigurableEngine{public FreeSwitchEngine(IOptions<PlatformOptions> o):base("freeswitch",TelephonyEngineKind.FreeSwitch,o.Value.Telephony.FreeSwitch){}async Task<string> Api(string command,CancellationToken ct){if(!Options.Enabled||string.IsNullOrWhiteSpace(Options.EslEndpoint)||string.IsNullOrWhiteSpace(Options.EslPassword))throw new InvalidOperationException("FreeSWITCH ESL is not configured");var p=Options.EslEndpoint.Split(':');using var tcp=new TcpClient();await tcp.ConnectAsync(p[0],p.Length>1?int.Parse(p[1]):8021,ct);await using var s=tcp.GetStream();using var r=new StreamReader(s,Encoding.UTF8,leaveOpen:true);await Frame(r,ct);await Write(s,$"auth {Options.EslPassword}\n\n",ct);if(!(await Frame(r,ct)).Contains("+OK accepted",StringComparison.OrdinalIgnoreCase))throw new UnauthorizedAccessException("ESL authentication failed");await Write(s,$"api {command}\n\n",ct);return await Frame(r,ct);}static async Task Write(Stream s,string v,CancellationToken ct){await s.WriteAsync(Encoding.UTF8.GetBytes(v),ct);await s.FlushAsync(ct);}static async Task<string> Frame(StreamReader r,CancellationToken ct){var h=new List<string>();var length=0;while(true){var l=await r.ReadLineAsync(ct)??throw new IOException("ESL disconnected");if(l.Length==0)break;h.Add(l);if(l.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase))int.TryParse(l.Split(':',2)[1].Trim(),out length);}if(length>0){var b=new char[length];await r.ReadBlockAsync(b.AsMemory(),ct);h.Add(new(b));}return string.Join("\n",h);}public override async Task<EngineHealth> ProbeAsync(CancellationToken ct){if(!Options.Enabled)return new(EngineKey,Kind,EngineAvailability.Disabled,"Disabled");try{await Api("status",ct);return new(EngineKey,Kind,EngineAvailability.Ready,"ESL authenticated");}catch(Exception e){return new(EngineKey,Kind,EngineAvailability.Unavailable,e.Message);}}public override async Task<OriginateResult> OriginateAsync(CallRequest r,CancellationToken ct){Valid(r);var id=Guid.NewGuid();var reply=await Api($"originate {{origination_uuid={id},origination_caller_id_number={r.CallerId}}}{r.TrunkKey??"sofia/gateway/default"}/{r.Destination} &park()",ct);if(reply.Contains("-ERR"))throw new InvalidOperationException(reply);return new(new(r.PlatformCallId,EngineKey,id.ToString()),"accepted",DateTimeOffset.UtcNow);}Task Act(CallRef c,string op,CancellationToken ct)=>Api($"uuid_{op} {c.EngineCallId}",ct);public override Task AnswerAsync(CallRef c,CancellationToken ct)=>Act(c,"answer",ct);public override Task HangupAsync(CallRef c,string r,CancellationToken ct)=>Act(c,$"kill {r}",ct);public override Task HoldAsync(CallRef c,bool e,CancellationToken ct)=>Act(c,e?"hold":"hold off",ct);public override Task SendDtmfAsync(CallRef c,string d,CancellationToken ct)=>Act(c,$"send_dtmf {d}",ct);public override Task TransferAsync(CallRef c,TransferRequest r,CancellationToken ct)=>Act(c,$"transfer {r.Destination}",ct);}
public sealed class AsteriskEngine:IcpaaS.Telephony.ConfigurableEngine{readonly HttpClient http=new();public AsteriskEngine(IOptions<PlatformOptions> o):base("asterisk",TelephonyEngineKind.Asterisk,o.Value.Telephony.Asterisk){if(!string.IsNullOrWhiteSpace(Options.AriUsername))http.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Basic",Convert.ToBase64String(Encoding.UTF8.GetBytes($"{Options.AriUsername}:{Options.AriPassword}")));}string Url(string p)=>$"{Options.AriBaseUrl?.TrimEnd('/')??throw new InvalidOperationException("ARI URL missing")}/{p}";async Task Send(HttpMethod m,string p,CancellationToken ct){var x=await http.SendAsync(new(m,Url(p)),ct);if(!x.IsSuccessStatusCode)throw new InvalidOperationException($"ARI returned {(int)x.StatusCode}: {await x.Content.ReadAsStringAsync(ct)}");}public override async Task<EngineHealth> ProbeAsync(CancellationToken ct){if(!Options.Enabled)return new(EngineKey,Kind,EngineAvailability.Disabled,"Disabled");try{await Send(HttpMethod.Get,"asterisk/info",ct);return new(EngineKey,Kind,EngineAvailability.Ready,"ARI authenticated");}catch(Exception e){return new(EngineKey,Kind,EngineAvailability.Unavailable,e.Message);}}public override async Task<OriginateResult> OriginateAsync(CallRequest r,CancellationToken ct){Valid(r);var id=Guid.NewGuid().ToString("N");await Send(HttpMethod.Post,$"channels/{id}?endpoint={Uri.EscapeDataString($"PJSIP/{r.Destination}@{r.TrunkKey??"default"}")}&app={Uri.EscapeDataString(Options.AriApp??"icpaas")}&callerId={Uri.EscapeDataString(r.CallerId??"")}",ct);return new(new(r.PlatformCallId,EngineKey,id),"accepted",DateTimeOffset.UtcNow);}Task Act(CallRef c,string p,HttpMethod m,CancellationToken ct)=>Send(m,$"channels/{c.EngineCallId}/{p}",ct);public override Task AnswerAsync(CallRef c,CancellationToken ct)=>Act(c,"answer",HttpMethod.Post,ct);public override Task HangupAsync(CallRef c,string r,CancellationToken ct)=>Act(c,"",HttpMethod.Delete,ct);public override Task HoldAsync(CallRef c,bool e,CancellationToken ct)=>Act(c,e?"hold":"unhold",HttpMethod.Post,ct);public override Task SendDtmfAsync(CallRef c,string d,CancellationToken ct)=>Act(c,$"dtmf?dtmf={Uri.EscapeDataString(d)}",HttpMethod.Post,ct);public override Task TransferAsync(CallRef c,TransferRequest r,CancellationToken ct)=>Act(c,$"redirect?endpoint={Uri.EscapeDataString(r.Destination)}",HttpMethod.Post,ct);}
public sealed class GenericSipEngine:IcpaaS.Telephony.ConfigurableEngine{readonly HttpClient http=new();public GenericSipEngine(IOptions<PlatformOptions> o):base("generic-sip",TelephonyEngineKind.GenericSip,o.Value.Telephony.GenericSip){if(!string.IsNullOrWhiteSpace(Options.ApiToken))http.DefaultRequestHeaders.Authorization=new("Bearer",Options.ApiToken);}async Task<JsonDocument> Post(string p,object b,CancellationToken ct){var url=Options.ControlWebhook?.TrimEnd('/')??throw new InvalidOperationException("Control webhook missing");var x=await http.PostAsync($"{url}/{p}",new StringContent(JsonSerializer.Serialize(b),Encoding.UTF8,"application/json"),ct);if(!x.IsSuccessStatusCode)throw new InvalidOperationException($"Gateway returned {(int)x.StatusCode}");return JsonDocument.Parse(await x.Content.ReadAsStringAsync(ct));}public override async Task<EngineHealth> ProbeAsync(CancellationToken ct){if(!Options.Enabled)return new(EngineKey,Kind,EngineAvailability.Disabled,"Disabled");try{var x=await http.GetAsync($"{Options.ControlWebhook?.TrimEnd('/')}/health",ct);return new(EngineKey,Kind,x.IsSuccessStatusCode?EngineAvailability.Ready:EngineAvailability.Degraded,$"Gateway {(int)x.StatusCode}");}catch(Exception e){return new(EngineKey,Kind,EngineAvailability.Unavailable,e.Message);}}public override async Task<OriginateResult> OriginateAsync(CallRequest r,CancellationToken ct){Valid(r);using var d=await Post("calls",r,ct);var id=d.RootElement.TryGetProperty("callId",out var v)?v.GetString():null;return new(new(r.PlatformCallId,EngineKey,id),"accepted",DateTimeOffset.UtcNow);}async Task Act(CallRef c,string p,object b,CancellationToken ct){using var _=await Post($"calls/{c.EngineCallId}/{p}",b,ct);}public override Task AnswerAsync(CallRef c,CancellationToken ct)=>Act(c,"answer",new{},ct);public override Task HangupAsync(CallRef c,string r,CancellationToken ct)=>Act(c,"hangup",new{reason=r},ct);public override Task HoldAsync(CallRef c,bool e,CancellationToken ct)=>Act(c,"hold",new{enabled=e},ct);public override Task SendDtmfAsync(CallRef c,string d,CancellationToken ct)=>Act(c,"dtmf",new{digits=d},ct);public override Task TransferAsync(CallRef c,TransferRequest r,CancellationToken ct)=>Act(c,"transfer",r,ct);}
